begin;
select set_config('app.sample_company_id',gen_random_uuid()::text,true);
select set_config('app.sample_operator_id',gen_random_uuid()::text,true);
select set_config('app.sample_reader_id',gen_random_uuid()::text,true);
select set_config('app.sample_outsider_id',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
 select current_setting(setting)::uuid,'authenticated','authenticated','sample+'||current_setting(setting)||'@invalid.test',now(),'{"provider":"email","providers":["email"]}'::jsonb,'{"display_name":"SAMPLE Operator"}'::jsonb,now(),now()
 from unnest(array['app.sample_operator_id','app.sample_reader_id','app.sample_outsider_id']) setting;
insert into public.companies(id,name,created_by) values(current_setting('app.sample_company_id')::uuid,'SAMPLE Administration Transfer Factory',current_setting('app.sample_operator_id')::uuid);
insert into public.plants(company_id,name) values(current_setting('app.sample_company_id')::uuid,'SAMPLE Plant');
insert into public.company_memberships(company_id,user_id) values(current_setting('app.sample_company_id')::uuid,current_setting('app.sample_operator_id')::uuid);
insert into public.user_company_roles(company_id,user_id,role) values(current_setting('app.sample_company_id')::uuid,current_setting('app.sample_operator_id')::uuid,'admin');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('app.sample_operator_id'),true);
do $$
declare c uuid:=current_setting('app.sample_company_id')::uuid;actor uuid:=current_setting('app.sample_operator_id')::uuid;reader uuid:=current_setting('app.sample_reader_id')::uuid;batch uuid;bad uuid;export uuid;item uuid;supplier uuid;req uuid;po uuid;grn uuid;lot uuid;wh uuid;loc uuid;payload jsonb;page jsonb;cursor bigint;
begin
 begin perform public.set_company_member_access(c,jsonb_build_object('user_id',actor,'roles',jsonb_build_array('stores'),'active',true,'expected_revision',1,'reason','SAMPLE denied last admin removal'),'last-admin');raise exception 'SAMPLE_LAST_ADMIN_REMOVED';exception when others then if sqlerrm<>'LAST_ADMIN_REQUIRED' then raise;end if;end;
 payload:=jsonb_build_object('user_id',reader,'roles',jsonb_build_array('planning'),'active',true,'expected_revision',0,'reason','SAMPLE approved planner');
 perform public.set_company_member_access(c,payload,'add-planner');perform public.set_company_member_access(c,payload,'add-planner');
 if jsonb_array_length(public.get_company_members(c))<>2 then raise exception 'SAMPLE_MEMBER_MISSING';end if;
 begin perform public.set_company_member_access(c,jsonb_set(payload,'{roles}','["admin"]'),'add-planner');raise exception 'SAMPLE_ACCESS_RETRY_CHANGED';exception when others then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',reader::text,true);
 begin perform public.get_company_members(c);raise exception 'SAMPLE_MEMBERS_LEAK';exception when others then if sqlerrm<>'FORBIDDEN' then raise;end if;end;
 begin perform public.set_company_member_access(c,jsonb_set(payload,'{roles}','["admin"]'),'escalate');raise exception 'SAMPLE_ROLE_ESCALATION';exception when others then if sqlerrm<>'FORBIDDEN' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 payload:=jsonb_build_object('kind','items','source_name','sample-items.csv','source_sha256',repeat('a',64),'rows',jsonb_build_array(jsonb_build_object('sku','SAMPLE-RAW','description','SAMPLE raw material','base_uom','kg')));
 batch:=public.preview_data_import(c,payload,'preview-items');
 if exists(select 1 from public.items where company_id=c and sku='SAMPLE-RAW') then raise exception 'SAMPLE_PREVIEW_POSTED';end if;
 perform public.apply_data_import(c,batch,'SAMPLE reviewed CSV','apply-items');perform public.apply_data_import(c,batch,'SAMPLE reviewed CSV','apply-items');
 select id into item from public.items where company_id=c and sku='SAMPLE-RAW';
 if (select count(*) from public.import_records where batch_id=batch)<>1 then raise exception 'SAMPLE_IMPORT_RECONCILIATION';end if;
 bad:=public.preview_data_import(c,payload,'duplicate-items');
 if (select jsonb_array_length(errors) from public.import_batches where id=bad)<>1 then raise exception 'SAMPLE_DUPLICATE_NOT_REPORTED';end if;
 begin perform public.apply_data_import(c,bad,'SAMPLE denied duplicate','apply-bad');raise exception 'SAMPLE_DUPLICATE_IMPORTED';exception when others then if sqlerrm<>'IMPORT_VALIDATION_FAILED' then raise;end if;end;
 insert into public.warehouses(company_id,plant_id,code,name) select c,id,'SAMPLE-W','SAMPLE Warehouse' from public.plants where company_id=c returning id into wh;
 insert into public.stock_locations(company_id,warehouse_id,code,name) values(c,wh,'SAMPLE-L','SAMPLE Location') returning id into loc;
 batch:=public.preview_data_import(c,jsonb_build_object('kind','opening_stock','source_name','sample-stock.csv','source_sha256',repeat('b',64),'rows',jsonb_build_array(jsonb_build_object('sku','SAMPLE-RAW','location_code','SAMPLE-L','lot_code','SAMPLE-OPEN','quantity','2.000001','uom','kg','reference','SAMPLE physical opening count'))),'preview-opening');
 perform public.apply_data_import(c,batch,'SAMPLE reconciled opening count','apply-opening');
 if not exists(select 1 from public.stock_lots where company_id=c and lot_code='SAMPLE-OPEN' and qc_status='hold') then raise exception 'SAMPLE_OPENING_NOT_HELD';end if;
 insert into public.suppliers(company_id,code,name) values(c,'SAMPLE-S','SAMPLE Supplier') returning id into supplier;
 req:=public.request_material(c,'SAMPLE-REQ',item,2.000001,'kg','SAMPLE demand',current_date,null,'req');
 po:=public.create_purchase_order(c,req,supplier,'SAMPLE-PO',0.1234,'INR',current_date,1,'po');perform public.approve_purchase_order(c,po,1,'po-ok');
 grn:=public.receive_purchase_order(c,po,'SAMPLE-GRN','SAMPLE-DELIVERY','SAMPLE heat','',loc,2.000001,'kg',2,'receipt');
 select lot_id into lot from public.goods_receipts where id=grn;perform public.return_goods_receipt(c,grn,0.5,'SAMPLE returned delivery',1,'return');
 export:=public.prepare_accounting_export(c,(now() at time zone 'Asia/Kolkata')::date,(now() at time zone 'Asia/Kolkata')::date,'export');
 if not exists(select 1 from public.accounting_export_batches b cross join lateral jsonb_array_elements(b.rows) r where b.id=export and r->>'event_type'='purchase_receipt' and (r->>'amount')::numeric=0.2468001234) then raise exception 'SAMPLE_EXPORT_AMOUNT_NOT_EXACT';end if;
 if not exists(select 1 from public.accounting_export_batches b cross join lateral jsonb_array_elements(b.rows) r where b.id=export and r->>'event_type'='supplier_return' and (r->>'amount')::numeric=-0.0617) then raise exception 'SAMPLE_EXPORT_RETURN_SIGN';end if;
 perform public.approve_accounting_export(c,export,'SAMPLE reviewed signed totals','export-ok');
 if jsonb_array_length(public.get_accounting_exports(c))<>1 then raise exception 'SAMPLE_EXPORT_HISTORY';end if;
 page:=public.get_company_audit_page(c,'export');if jsonb_array_length(page->'rows')<>2 then raise exception 'SAMPLE_AUDIT_FILTER';end if;
 cursor:=((page->'rows'->0)->>'id')::bigint;
 if jsonb_array_length(public.get_company_audit_page(c,'export',cursor)->'rows')<>1 then raise exception 'SAMPLE_AUDIT_CURSOR';end if;
 perform public.set_company_member_access(c,jsonb_build_object('user_id',reader,'roles',jsonb_build_array('planning'),'active',false,'expected_revision',1,'reason','SAMPLE revoked access'),'deactivate');
 perform set_config('request.jwt.claim.sub',reader::text,true);
 if private.has_company_permission(c,'master_data.read') then raise exception 'SAMPLE_INACTIVE_ACCESS';end if;
 perform set_config('request.jwt.claim.sub',current_setting('app.sample_outsider_id'),true);
 if exists(select 1 from public.import_batches where company_id=c) or exists(select 1 from public.accounting_export_batches where company_id=c) then raise exception 'SAMPLE_TRANSFER_TENANT_LEAK';end if;
 begin perform public.get_company_audit_page(c);raise exception 'SAMPLE_AUDIT_TENANT_LEAK';exception when others then if sqlerrm<>'FORBIDDEN' then raise;end if;end;
end $$;
rollback;
